mapper.select:

 AND c.factory_id=#{factoryId}
 AND c.factory_id=#{q.factoryId}
 AND c.customer_name LIKE #{q.namePattern} ESCAPE '!'
 AND c.company_name LIKE #{q.companyNamePattern} ESCAPE '!'
 AND c.contact_name LIKE #{q.contactNamePattern} ESCAPE '!'
 AND c.contact_phone LIKE #{q.contactPhonePattern} ESCAPE '!'
 AND c.create_time >=#{q.startTime}
 AND c.create_time <#{q.endExclusive}
ORDER BY c.customer_id DESC
